	a.print(prompt)
	if !a.in.Scan() {
		return "", false
	}
	// Mantém os espaços do início e do meio para as posições dos tokens
	// baterem com o que foi digitado.
	return strings.TrimRight(a.in.Text(), "\r"), true
}

