func (t *Table) Production(nonTerminal, column string) (Production, bool) {
	number, ok := t.Cells[nonTerminal][column]
	if !ok {
		return Production{}, false
	}
	// Os números começam em 1 e seguem a ordem de Productions.
	return t.Grammar.Productions[number-1], true
}

func (t *Table) place(p Production, column string) {
	row := t.Cells[p.Head]
	if existing, taken := row[column]; taken {
		t.Conflicts = append(t.Conflicts, fmt.Sprintf(
			"Conflito em M[%s, %s]: produções %d e %d", p.Head, column, existing, p.Number))
		t.recordConflict(p, column, existing)
		return
	}
	row[column] = p.Number
}

func (t *Table) recordConflict(p Production, column string, existing int) {
	for i, cell := range t.ConflictCells {
		if cell.NonTerminal == p.Head && cell.Column == column {
			t.ConflictCells[i].Numbers = append(cell.Numbers, p.Number)
			return
		}
	}
	t.ConflictCells = append(t.ConflictCells, ConflictCell{
		NonTerminal: p.Head,
		Column:      column,
		Numbers:     []int{existing, p.Number},
	})
}

func Tokenize(input string) ([]Token, error) {
	return TokenizeFor(Default(), input)
}

func TokenizeFor(g *Grammar, input string) ([]Token, error) {
	runes := []rune(input)
	var tokens []Token
	for i := 0; i < len(runes); {
		r := runes[i]
		start := i
		switch {
		case isSpace(r):
			i++
			continue
		case isLetter(r):
			for i < len(runes) && (isLetter(runes[i]) || isDigit(runes[i])) {
				i++
			}
			word := string(runes[start:i])
			kind := TerminalID
			if g.isKeyword(word) {
				kind = word
			}
			tokens = append(tokens, Token{Kind: kind, Lexeme: word, Pos: start + 1})
		case isDigit(r):
			for i < len(runes) && isDigit(runes[i]) {
				i++
			}
			tokens = append(tokens, Token{Kind: TerminalNum, Lexeme: string(runes[start:i]), Pos: start + 1})
		case g.IsTerminal(string(r)):
			i++
			tokens = append(tokens, Token{Kind: string(r), Lexeme: string(r), Pos: start + 1})
		default:
			return nil, &LexicalError{Char: r, Pos: start + 1}
		}
	}
	tokens = append(tokens, Token{Kind: EndMarker, Lexeme: EndMarker, Pos: len(runes) + 1})
	return tokens, nil
}

func chooseProduction(options []Production, heights map[int]int, rng *rand.Rand, shortest bool) Production {
	if shortest {
		best := math.MaxInt
		var fastest []Production
		for _, p := range options {
			switch h := heights[p.Number]; {
			case h < best:
				best = h
				fastest = []Production{p}
			case h == best:
				fastest = append(fastest, p)
			}
		}
		options = fastest
	}
	return options[rng.Intn(len(options))]
}

func contains(list []string, s string) bool {
	for _, item := range list {
		if item == s {
			return true
		}
	}
	return false
}

func describeSymbol(symbol string) string {
	if symbol == EndMarker {
		return "fim da entrada"
	}
	return "'" + symbol + "'"
}

func grammarFrom(rules string) *Grammar {
	g := &Grammar{}
	type rule struct{ head, body string }
	var parsed []rule
	for _, line := range strings.Split(rules, "\n") {
		head, body, found := strings.Cut(line, strings.TrimSpace(Arrow))
		if !found {
			continue
		}
		head = strings.TrimSpace(head)
		g.NonTerminals = append(g.NonTerminals, head)
		parsed = append(parsed, rule{head, body})
	}
	g.Start = g.NonTerminals[0]
	for _, r := range parsed {
		for _, alternative := range strings.Split(r.body, alternativeSeparator) {
			body := withoutInnerEpsilon(strings.Fields(alternative))
			for _, symbol := range body {
				if symbol != Epsilon && !g.IsNonTerminal(symbol) && !g.IsTerminal(symbol) {
					g.Terminals = append(g.Terminals, symbol)
				}
			}
			g.Productions = append(g.Productions, Production{Number: len(g.Productions) + 1, Head: r.head, Body: body})
		}
	}
	return g
}

func insertAt(lexemes []string, i int, lexeme string) []string {
	result := append([]string{}, lexemes[:i]...)
	result = append(result, lexeme)
	return append(result, lexemes[i:]...)
}

func isDigit(r rune) bool {
	return r >= '0' && r <= '9'
}

func isLetter(r rune) bool {
	return r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}

func isSpace(r rune) bool {
	return r == ' ' || r == '\t' || r == '\r' || r == '\n'
}

func kinds(tokens []Token) []string {
	result := make([]string, len(tokens))
	for i, token := range tokens {
		result[i] = token.Kind
	}
	return result
}

func lexemeFor(terminal string, rng *rand.Rand) string {
	switch terminal {
	case TerminalID:
		return identifierLexemes[rng.Intn(len(identifierLexemes))]
	case TerminalNum:
		return strconv.Itoa(rng.Intn(maxNumberLexeme + 1))
	default:
		return terminal
	}
}

func lexicalFailure(g *Grammar, start []string, input string, lexErr *LexicalError) Result {
	prefix := string([]rune(input)[:lexErr.Pos-1])
	read, _ := TokenizeFor(g, prefix)
	read = read[:len(read)-1] // tira o "$" do prefixo
	remaining := append(kinds(read), string(lexErr.Char), EndMarker)
	step := Step{
		Number: 1,
		Stack:  start,
		Input:  remaining,
		Action: ErrorPrefix + " léxico: " + lexErr.Detail(),
	}
	return Result{
		Message: fmt.Sprintf(messageRejected, lexErr.Error()),
		Tokens:  read,
		Steps:   []Step{step},
	}
}

func matchAction(token Token) string {
	if token.Lexeme == token.Kind {
		return fmt.Sprintf("Casa '%s'", token.Kind)
	}
	return fmt.Sprintf("Casa '%s' (%s)", token.Kind, token.Lexeme)
}

func mutate(g *Grammar, lexemes []string, rng *rand.Rand) []string {
	operators := g.punctuation()
	const (
		dropToken = iota
		duplicateOperator
		unbalancedParenthesis
		illegalCharacter
		mutationCount
	)
	switch rng.Intn(mutationCount) {
	case dropToken:
		if len(lexemes) == 0 {
			return lexemes
		}
		i := rng.Intn(len(lexemes))
		return append(append([]string{}, lexemes[:i]...), lexemes[i+1:]...)
	case duplicateOperator:
		var operatorIndexes []int
		for i, lexeme := range lexemes {
			if contains(operators, lexeme) {
				operatorIndexes = append(operatorIndexes, i)
			}
		}
		if len(operatorIndexes) > 0 {
			i := operatorIndexes[rng.Intn(len(operatorIndexes))]
			return insertAt(lexemes, i, lexemes[i])
		}
		if len(operators) == 0 {
			return lexemes
		}
		return insertAt(lexemes, rng.Intn(len(lexemes)+1), operators[0])
	case unbalancedParenthesis:
		parenthesis := []string{"(", ")"}[rng.Intn(2)]
